interface Frame {
  type: string;
  sessionId?: string;
  sessions?: Array<{sessionId: string; createdAt: string; updatedAt: string; entryCount: number}>;
  code?: string;
  message?: string;
}

const startEngine = async (sessionStore: SessionStore, userId: string | number = 'u1') => {
  const {url} = await startEngineWith({
    create: createServer,
    sessionStore,
    wsAuth: async () => ({id: userId}),
  });
